$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Speech

function Get-RequiredVoice($Synthesizer) {
  $voice = $synthesizer.GetInstalledVoices() |
    ForEach-Object VoiceInfo |
    Where-Object {
      $_.Name -eq 'Microsoft Kangkang' -and
      $_.Culture.Name -eq 'zh-CN' -and
      $_.Gender -eq [System.Speech.Synthesis.VoiceGender]::Male
    } |
    Select-Object -First 1

  if ($null -eq $voice) {
    throw 'Required Mandarin male voice Microsoft Kangkang (zh-CN, Male) is not installed.'
  }
  return $voice
}

function Invoke-KangkangSpeech([string]$Text, [string]$Destination, [int]$SpeechRate) {
  $synthesizer = [System.Speech.Synthesis.SpeechSynthesizer]::new()
  try {
    $voice = Get-RequiredVoice $synthesizer
    $synthesizer.SelectVoice($voice.Name)
    $synthesizer.Rate = $SpeechRate
    $synthesizer.Volume = 100
    $synthesizer.SetOutputToWaveFile($Destination)
    $synthesizer.Speak($Text)
  } finally {
    $synthesizer.Dispose()
  }
}

function Get-WavMetadata([string]$Path) {
  $bytes = [System.IO.File]::ReadAllBytes($Path)
  if ($bytes.Length -lt 44 -or [Text.Encoding]::ASCII.GetString($bytes, 0, 4) -ne 'RIFF' -or [Text.Encoding]::ASCII.GetString($bytes, 8, 4) -ne 'WAVE') {
    throw "Expected RIFF/WAVE PCM file: $Path"
  }
  $chunkOffset = 12
  $dataOffset = -1
  $dataSize = 0
  while ($chunkOffset + 8 -le $bytes.Length) {
    $chunkSize = [BitConverter]::ToUInt32($bytes, $chunkOffset + 4)
    if ([Text.Encoding]::ASCII.GetString($bytes, $chunkOffset, 4) -eq 'data') {
      $dataOffset = $chunkOffset + 8
      $dataSize = $chunkSize
      break
    }
    $chunkOffset += 8 + $chunkSize + ($chunkSize % 2)
  }
  if ($dataOffset -lt 0) { throw "WAV data chunk is missing: $Path" }
  $byteRate = [BitConverter]::ToUInt32($bytes, 28)
  $metadata = [pscustomobject]@{
    AudioFormat = [BitConverter]::ToUInt16($bytes, 20)
    Channels = [BitConverter]::ToUInt16($bytes, 22)
    SampleRate = [BitConverter]::ToUInt32($bytes, 24)
    ByteRate = $byteRate
    BitsPerSample = [BitConverter]::ToUInt16($bytes, 34)
    DataOffset = $dataOffset
    DataSize = $dataSize
    DurationSeconds = [Math]::Round($dataSize / [double]$byteRate, 6)
  }
  if ($metadata.AudioFormat -ne 1 -or $metadata.DataOffset + $metadata.DataSize -gt $bytes.Length) { throw "WAV is not valid PCM: $Path" }
  return $metadata
}

function Write-PcmTimeline([object[]]$SelectedCues, [object]$Format, [int]$TargetDurationSeconds, [string]$Destination) {
  $dataLength = [int]($Format.ByteRate * $TargetDurationSeconds)
  $timeline = [byte[]]::new($dataLength)
  foreach ($cue in $SelectedCues) {
    $metadata = $cue.Metadata
    if ($metadata.Channels -ne $Format.Channels -or $metadata.SampleRate -ne $Format.SampleRate -or $metadata.BitsPerSample -ne $Format.BitsPerSample) {
      throw "Cue $($cue.Index) does not match the PCM format of cue 1."
    }
    $bytes = [System.IO.File]::ReadAllBytes($cue.File)
    $offset = [int]($cue.Start * $Format.ByteRate)
    if ($metadata.DataSize -gt [int](($cue.End - $cue.Start) * $Format.ByteRate)) { throw "Cue $($cue.Index) would require trimming." }
    [Array]::Copy($bytes, $metadata.DataOffset, $timeline, $offset, $metadata.DataSize)
  }
  $stream = [System.IO.File]::Open($Destination, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write)
  try {
    $writer = [System.IO.BinaryWriter]::new($stream)
    $writer.Write([Text.Encoding]::ASCII.GetBytes('RIFF'))
    $writer.Write([int](36 + $dataLength))
    $writer.Write([Text.Encoding]::ASCII.GetBytes('WAVEfmt '))
    $writer.Write([int]16)
    $writer.Write([int16]1)
    $writer.Write([int16]$Format.Channels)
    $writer.Write([int]$Format.SampleRate)
    $writer.Write([int]$Format.ByteRate)
    $writer.Write([int16]($Format.Channels * ($Format.BitsPerSample / 8)))
    $writer.Write([int16]$Format.BitsPerSample)
    $writer.Write([Text.Encoding]::ASCII.GetBytes('data'))
    $writer.Write([int]$dataLength)
    $writer.Write($timeline)
    $writer.Flush()
  } finally {
    $stream.Dispose()
  }
}

