      break
    }
  }
  if ($null -eq $chosen) { throw "Cue $($cue.index) cannot fit its window at System.Speech rates -1 through 4." }
  $selected += $chosen
}

Write-PcmTimeline $selected $selected[0].Metadata ([int]$plan.targetDurationSeconds) $OutputWav
$finalMetadata = Get-WavMetadata $OutputWav
if ($finalMetadata.DurationSeconds -ne [double]$plan.targetDurationSeconds) { throw "Final narration duration $($finalMetadata.DurationSeconds) is not $($plan.targetDurationSeconds) seconds." }
